{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "Ensure that VPC Flow Logs is enabled for every subnet in a VPC Network",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnetwork does not have log_config defined, meaning VPC Flow Logs are disabled. This prevents network traffic monitoring and security auditing for the data subnet."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name          = "insurance-claims-processing-platform-subnet-data"
  ip_cidr_range = "10.0.3.0/24"
  region        = var.region
  network       = google_compute_network.claims_vpc.id
  description   = "Data subnet for Cloud SQL database"
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}",
  "fix_summary": "Added a `log_config` block to the `google_compute_subnetwork` resource to enable VPC Flow Logs with standard settings (5-second aggregation, 50% sampling, all metadata included)."
}
